# Câu 3 (đề in 'Cho |x| = 16 thì giá trị của x là - NB'): đã bỏ chữ 'NB' (ghi chú mức độ của ma trận, lẫn vào đề).
# Câu 14: đề không viết chữ nhưng hình có hai cung đánh dấu bằng nhau tại C nên CD là tia phân giác của góc ACB (D ∈ AB); x = ∠ACD, y = ∠BDC. Đáp án 25° và 115° khớp.
# Câu 13: nhãn của phần 'Cam' không in trên biểu đồ; 28% suy ra từ 100% − 35% − 20% − 17% (cũng khớp với HDC: ý a đúng).
# LỖI HDC Bài 3b: ghi 'Cạnh góc vuông – góc nhọn kề' — sai tên trường hợp: IB và IC là CẠNH HUYỀN của hai tam giác vuông IHB, IKC nên phải là 'cạnh huyền – góc nhọn'. Kết luận △IHB = △IKC vẫn đúng.
# LỖI HDC Bài 3c: ghi 'góc EHI = góc KFI (IH⊥AB, IK⊥AC)' — sai cặp góc; đúng là ∠EHI = ∠FKI = 90° (H, K là các đỉnh tương ứng của △HIE và △KIF). Kết luận △HIE = △KIF (g.c.g) vẫn đúng.
# LỖI HDC Bài 3d: 'góc AHK = 180° − góc EAF (1)' và 'góc AEF = 180° − góc EAF (2)' thiếu chia 2 (đúng: ∠AHK = (180° − ∠EAF)/2 và ∠AEF = (180° − ∠EAF)/2). Kết luận ∠AEF = ∠AHK ở vị trí đồng vị ⇒ HK // EF vẫn đúng. HDC cũng không nói rõ HB = KC suy ra từ △IHB = △IKC (đã bổ sung).
# LỖI ĐỀ + HDC Bài 4 (NGHIÊM TRỌNG, đã kiểm tra bằng Python): với A = 5 + 5² + 5³ + ... + 5^2022 thì A chia hết cho 31 (đúng) nhưng A chia 26 dư 4 (A ≡ 186 mod 806), nên A KHÔNG chia hết cho 26 và KHÔNG chia hết cho 806. Cách nhóm thứ hai của HDC (nhóm (5 + 5³), (5² + 5⁴), ...) sai vì 2022 không chia hết cho 4. Đề chỉ đúng nếu số số hạng chia hết cho 12 (ví dụ A = 5 + 5² + ... + 5^2016). Entry Bài 4 vẫn để dạng essay, explanation ghi HDC gốc rồi LƯU Ý nêu rõ phản chứng.
